insert into public.lesson_steps (id, lesson_id, kind, sort_order, points, content) values (md5('step:smm-foundations:ads-manager:1')::uuid, md5('lesson:smm-foundations:ads-manager')::uuid, 'text', 1, 0, '{"title":"Гурван түвшин","body":["Ads Manager дахь зар сурталчилгаа гурван түвшинтэй: Campaign (зорилго), Ad set (хэнд, хэзээ, хаана, хэдэн төгрөгөөр), Ad (хэрэглэгч харах креатив, текст, CTA).","Campaign түвшинд зорилгоо сонгоно. Одоогийн Meta-ийн зорилгууд ерөнхийдөө Awareness, Traffic, Engagement, Leads, App promotion, Sales гэсэн бүлэгт хуваагддаг (нэршил өөрчлөгдөж болно)."],"tip":"Зорилгоо буруу сонговол систем буруу үр дүнд оновчилно — энэ нь хамгийн түгээмэл алдаа."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, points = excluded.points, content = excluded.content;
