on conflict (step_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.lesson_steps (id, lesson_id, kind, sort_order, points, content) values (md5('step:smm-foundations:ads-manager:3')::uuid, md5('lesson:smm-foundations:ads-manager')::uuid, 'single_choice', 3, 10, '{"prompt":"Онлайн дэлгүүр вэбсайт дээрх худалдан авалтыг нэмэгдүүлэхийг хүсч байна. Аль зорилго хамгийн тохирох вэ?","options":[{"id":"a","label":"Awareness"},{"id":"b","label":"Sales"},{"id":"c","label":"Engagement"}]}'::jsonb)
