insert into public.lesson_steps (id, lesson_id, kind, sort_order, points, content) values (md5('step:smm-foundations:targeting-analytics:1')::uuid, md5('lesson:smm-foundations:targeting-analytics')::uuid, 'text', 1, 0, '{"title":"Хэнд хүрэх вэ, яаж хэмжих вэ?","body":["Зорилтот бүлгийн гурван ерөнхий төрөл: байршил/нас/сонирхолд суурилсан бүлэг, өөрийн мэдээлэлд (вэбсайтын зочид, хэрэглэгчийн жагсаалт) суурилсан custom бүлэг, тэдэнтэй төстэй lookalike бүлэг. Meta-ийн автомат (Advantage+) сонголтууд ч байдаг.","Түгээмэл үзүүлэлтүүд: Reach (хүрсэн хүний тоо), Impressions (харагдсан удаа), CTR (дарсан хувь), CPC (нэг дарагдалтын өртөг), CPM (1000 харагдалтын өртөг), CPA/CPL (нэг үр дүнгийн өртөг)."],"tip":"Хэрэглэгчийн жагсаалт ашиглахдаа тэдний зөвшөөрөл, хувийн мэдээллийн хуулийн шаардлагыг заавал хангана."}'::jsonb)
on conflict (id) do update set kind = excluded.kind, points = excluded.points, content = excluded.content;
insert into public.lesson_steps (id, lesson_id, kind, sort_order, points, content) values (md5('step:smm-foundations:targeting-analytics:2')::uuid, md5('lesson:smm-foundations:targeting-analytics')::uuid, 'single_choice', 2, 10, '{"prompt":"1,000 удаа харагдаж (impressions), 20 удаа дарагдсан бол CTR хэд вэ?","options":[{"id":"a","label":"0.2%"},{"id":"b","label":"2%"},{"id":"c","label":"20%"}]}'::jsonb)
on conflict (id) do update set kind = excluded.kind, points = excluded.points, content = excluded.content;
insert into public.lesson_step_keys (step_id, answer, explanation) values (md5('step:smm-foundations:targeting-analytics:2')::uuid, '{"correct":"b"}'::jsonb, 'CTR = clicks ÷ impressions × 100 = 20 ÷ 1000 × 100 = 2%.')
on conflict (step_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.lesson_steps (id, lesson_id, kind, sort_order, points, content) values (md5('step:smm-foundations:targeting-analytics:3')::uuid, md5('lesson:smm-foundations:targeting-analytics')::uuid, 'single_choice', 3, 10, '{"prompt":"60,000₮ зарцуулж 30 lead авсан бол CPL хэд вэ?","options":[{"id":"a","label":"2,000₮"},{"id":"b","label":"1,800,000₮"},{"id":"c","label":"30₮"}]}'::jsonb)
on conflict (id) do update set kind = excluded.kind, points = excluded.points, content = excluded.content;
insert into public.lesson_step_keys (step_id, answer, explanation) values (md5('step:smm-foundations:targeting-analytics:3')::uuid, '{"correct":"a"}'::jsonb, 'CPL = зарцуулалт ÷ lead = 60,000 ÷ 30 = 2,000₮.')
on conflict (step_id) do update set answer = excluded.answer, explanation = excluded.explanation;
insert into public.lesson_steps (id, lesson_id, kind, sort_order, points, content) values (md5('step:smm-foundations:targeting-analytics:4')::uuid, md5('lesson:smm-foundations:targeting-analytics')::uuid, 'scenario', 4, 10, '{"context":"Хоёр зар ижил төсөвтэй. Зар А: CTR 3%, нэг захиалгын өртөг 25,000₮. Зар Б: CTR 1%, нэг захиалгын өртөг 12,000₮. Зорилго — захиалга.","prompt":"Аль зар бизнесийн зорилгод илүү үр дүнтэй вэ?","options":[{"id":"a","label":"Зар А — CTR өндөр"},{"id":"b","label":"Зар Б — нэг захиалгын өртөг бага"},{"id":"c","label":"Хоёулаа адилхан"}]}'::jsonb)
on conflict (id) do update set kind = excluded.kind, points = excluded.points, content = excluded.content;
insert into public.lesson_step_keys (step_id, answer, explanation) values (md5('step:smm-foundations:targeting-analytics:4')::uuid, '{"correct":"b"}'::jsonb, 'Зорилго захиалга бол нэг үр дүнгийн өртөг (CPA) гол хэмжүүр. CTR нь туслах үзүүлэлт.')
on conflict (step_id) do update set answer = excluded.answer, explanation = excluded.explanation;
